         \n188:            PERFORM UNTIL END-OF-FILE = 'Y'                                      \n189:                IF  END-OF-FILE = 'N'                                            \n190:                    PERFORM 1000-TCATBALF-GET-NEXT                               \n191:                    IF  END-OF-FILE = 'N'                                        \n192:                      ADD 1 TO WS-RECORD-COUNT                                   \n193:                      DISPLAY TRAN-CAT-BAL-RECORD                                \n194:                      IF TRANCAT-ACCT-ID NOT= WS-LAST-ACCT-NUM                   \n195:                        IF WS-FIRST-TIME NOT = 'Y'                               \n196:                           PERFORM 1050-UPDATE-ACCOUNT                           \n197:                        ELSE                                                     \n198:                           MOVE 'N' TO WS-FIRST-TIME                             \n199:                        END-IF                                                   \n200:                        MOVE 0 TO WS-TOTAL-INT                                   \n201:                        MOVE TRANCAT-ACCT-ID TO WS-LAST-ACCT-NUM                 \n202:                        MOVE TRANCAT-ACCT-ID TO FD-ACCT-ID                       \n203:                        PERFORM 1100-GET-ACCT-DATA                               \n204:                        MOVE TRANCAT-ACCT-ID TO FD-XREF-ACCT-ID                  \n205:                        PERFORM 1110-GET-XREF-DATA                               \n206:                      END-IF                                                     \n207:       *              DISPLAY 'ACCT-GROUP-ID: ' ACCT-GROUP-ID                    \n208:       *              DISPLAY 'TRANCAT-CD: ' TRANCAT-CD                          \n209:       *              DISPLAY 'TRANCAT-TYPE-CD: ' TRANCAT-TYPE-CD                \n210:                      MOVE ACCT-GROUP-ID TO FD-DIS-ACCT-GROUP-ID       