                    \n441:                                                                                 \n442:       *---------------------------------------------------------------*         \n443:        1200-A-GET-DEFAULT-INT-RATE.                                             \n444:            READ DISCGRP-FILE INTO DIS-GROUP-RECORD                              \n445:                                                                                 \n446:            IF  DISCGRP-STATUS  = '00'                                           \n447:                MOVE 0 TO APPL-RESULT                                            \n448:            ELSE                                                                 \n449:                MOVE 12 TO APPL-RESULT                                           \n450:            END-IF                                                               \n451:                                                                                 \n452:            IF  APPL-AOK                                                         \n453:                CONTINUE                                                         \n454:            ELSE                                                                 \n455:                DISPLAY 'ERROR READING DEFAULT DISCLOSURE GROUP'                 \n456:                MOVE DISCGRP-STATUS  TO IO-STATUS                                \n457:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n458:                PERFORM 9999-ABEND-PROGRAM                                       \n459:            END-IF                                                               \n460:            EXIT.                                                                \n461:       *---------------------------------------------------------------*         \n462:        1300-COMPUTE-INTEREST.                                                   \n463:                                                                                 \n464:            COMPUTE WS-MONTHLY-INT                                               \n465:             = ( TRAN-CAT-BAL * DIS-INT-RATE) / 1200                             \n466:                                                                                 \n467:            ADD WS-MONTHLY-INT  TO WS-TOTAL-INT                                  \n468:            PERFORM 1300-B-WRITE-TX.                                             \n469:                                                                                 \n470:            EXIT.                                                                \n471:                                                                                 \n472:       *---------------------------------------------------------------*         \n473:        1300-B-WRITE-TX.                                                         \n474:            ADD 1 TO WS-TRANID-SUFFIX                                            \n475:                                                                                 \n476:            STRING PARM-DATE,                                                    \n477:                   WS-TRANID-SUFFIX                                              \n478:              DELIMITED BY SIZE                                                  \n479:              INTO TRAN-ID                                                       \n480:            END-STRING.                                                          \n481:                                                                                 \n482:            MOVE '01'                 TO TRAN-TYPE-CD                            \n483:            MOVE '05'                 TO TRAN-CAT-CD                             \n484:            MOVE 'System'             TO TRAN-SOURCE                             \n485:            STRING 'Int. for a/c ' ,                                             \n486:                   ACCT-ID                                                       \n487:                   DELIMITED BY SIZE                                             \n488:             INTO TRAN-DESC                                                      \n489:            END-STRING                                                           \n490:            MOVE WS-MONTHLY-INT       TO TRAN-AMT                                \n491:            MOVE 0                    TO TRAN-MERCHANT-ID                        \n492:            MOVE SPACES               TO TRAN-MERCHANT-NAME                      \n493:            MOVE SPACES               TO TRAN-MERCHANT-CITY                      \n494:            MOVE SPACES               TO TRAN-MERCHANT-ZIP                       \n495:            MOVE XREF-CARD-NUM        TO TRAN-CARD-NUM                           \n496:            PERFORM Z-GET-DB2-FORMAT-TIMESTAMP                                   \n497:            MOVE DB2-FORMAT-TS        TO TRAN-ORIG-TS                            \n498:            MOVE DB2-FORMAT-TS        TO TRAN-PROC-TS                            \n499:                                                                                 \n500:            WRITE FD-TRANFILE-REC FROM TRAN-RECORD                               \n501:            IF  TRANFILE-STATUS   = '00'                                         \n502:                MOVE 0 TO APPL-RESULT                                            \n503:            ELSE                                                                 \n504:                MOVE 12 TO APPL-RESULT                                           \n505:            END-IF                                                               \n506:                                                                                 \n507:            IF  APPL-AOK                                                         \n508:                CONTINUE                                                         \n509:            ELSE                                                                 \n510:                DISPLAY 'ERROR WRITING TRANSACTION RECORD'                       \n511:                MOVE TRANFILE-STATUS   TO IO-STATUS                              \n512:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n513:                PERFORM 9999-ABEND-PROGRAM                                       \n514:            END-IF                                                               \n515:            EXIT.                                                                \n516:                                                                                 \n517:       *---------------------------------------------------------------*         \n518:        1400-COMPUTE-FEES.                                                       \n519:       * To be implemented                                                       \n520:            EXIT.                                                                \n521:       *---------------------------------------------------------------*         \n522:        9000-TCATBALF-CLOSE.                                                     \n523:            MOVE 8 TO  APPL-RESULT.                                              \n524:            CLOSE TCATBAL-FILE                                                   \n525:            IF  TCATBALF-STATUS = '00'                                           \n526:                MOVE 0 TO  APPL-RESULT                                           \n527:            ELSE                                                                 \n528:                MOVE 12 TO APPL-RESULT                                           \n529:            END-IF                                                               \n530:            IF  APPL-AOK                                                         \n531:                CONTINUE                                                         \n532:            ELSE                                                                 \n533:                DISPLAY 'ERROR CLOSING TRANSACTION BALANCE FILE'                 \n534:                MOVE TCATBALF-STATUS  TO IO-STATUS                               \n535:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n536:                PERFORM 9999-ABEND-PROGRAM                                       \n537:            END-IF                                                               \n538:            EXIT.                                                                \n539:                                                                                 \n540:       *---------------------------------------------------------------*         \n541:        9100-XREFFILE-CLOSE.                                                     \n542:            MOVE 8 TO APPL-RESULT.                                               \n543:            CLOSE XREF-FILE                                                      \n544:            IF  XREFFILE-STATUS = '00'                                           \n545:                MOVE 0 TO APPL-RESULT                                            \n546:            ELSE                                                                 \n547:                MOVE 12 TO APPL-RESULT                                           \n548:            END-IF                                                               \n549:            IF  APPL-AOK                                                         \n550:                CONTINUE                                                         \n551:            ELSE                                                                 \n552:                DISPLAY 'ERROR CLOSING CROSS REF FILE'                           \n553:                MOVE XREFFILE-STATUS TO IO-STATUS                                \n554:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n555:                PERFORM 9999-ABEND-PROGRAM                                       \n556:            END-IF                                                               \n557:            EXIT.                                                                \n558:       *---------------------------------------------------------------*         \n559:        9200-DISCGRP-CLOSE.                                                      \n560:            MOVE 8 TO APPL-RESULT.                                               \n561:            CLOSE DISCGRP-FILE                                                   \n562:            IF  DISCGRP-STATUS = '00'                                            \n563:                MOVE 0 TO APPL-RESULT                                            \n564:            ELSE                                                                 \n565:                MOVE 12 TO APPL-RESULT                                           \n566:            END-IF                                                               \n567:            IF  APPL-AOK                                                         \n568:                CONTINUE                                                         \n569:            ELSE                                                                 \n570:                DISPLAY 'ERROR CLOSING DISCLOSURE GROUP FILE'                    \n571:                MOVE DISCGRP-STATUS TO IO-STATUS                                 \n572:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n573:                PERFORM 9999-ABEND-PROGRAM                                       \n574:            END-IF                                                               \n575:            EXIT.                                                                \n576:       *---------------------------------------------------------------*         \n577:        9300-ACCTFILE-CLOSE.                                                     \n578:            MOVE 8 TO APPL-RESULT.                                               \n579:            CLOSE ACCOUNT-FILE                                                   \n580:            IF  ACCTFILE-STATUS  = '00'                                          \n581:                MOVE 0 TO APPL-RESULT                                            \n582:            ELSE                                                                 \n583:                MOVE 12 TO APPL-RESULT                                           \n584:            END-IF                                                               \n585:            IF  APPL-AOK                                                         \n586:                CONTINUE                                                         \n587:            ELSE                                                                 \n588:                DISPLAY 'ERROR CLOSING ACCOUNT FILE'                             \n589:                MOVE ACCTFILE-STATUS  TO IO-STATUS                               \n590:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n591:                PERFORM 9999-ABEND-PROGRAM                                       \n592:            END-IF                                                               \n593:            EXIT.                                                                \n594:                                                                                 \n595:        9400-TRANFILE-CLOSE.                                                     \n596:            MOVE 8 TO APPL-RESULT.                                               \n597:            CLOSE TRANSACT-FILE                                                  \n598:            IF  TRANFILE-STATUS  = '00'                                          \n599:                MOVE 0 TO APPL-RESULT                                            \n600:            ELSE                                                                 \n601:                MOVE 12 TO APPL-RESULT                                           \n602:            END-IF                                                               \n603:            IF  APPL-AOK                                                         \n604:                CONTINUE                                                         \n605:            ELSE                                                                 \n606:                DISPLAY 'ERROR CLOSING TRANSACTION FILE'                         \n607:                MOVE TRANFILE-STATUS  TO IO-STATUS                               \n608:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n609:                PERFORM 9999-ABEND-PROGRAM                                       \n610:            END-IF                                                               \n611:            EXIT.                                                                \n612:                                                                                 \n613:        Z-GET-DB2-FORMAT-TIMESTAMP.                                              \n614:            MOVE FUNCTION CURRENT-DATE TO COBOL-TS                               \n615:            MOVE COB-YYYY TO DB2-YYYY                                            \n616:            MOVE COB-MM   TO DB2-MM                                              \n617:            MOVE COB-DD   TO DB2-DD                                              \n618:            MOVE COB-HH   TO DB2-HH                                              \n619:            MOVE COB-MIN  TO DB2-MIN                                             \n620:            MOVE COB-SS   TO DB2-SS                                              \n621:            MOVE COB-MIL  TO DB2-MIL                                             \n622:            MOVE '0000'   TO DB2-REST                                            \n623:            MOVE '-' TO DB2-STREEP-1 DB2-STREEP-2 DB2-STREEP-3                   \n624:            MOVE '.' TO DB2-DOT-1 DB2-DOT-2 DB2-DOT-3                            \n625:       *    DISPLAY 'DB2-TIMESTAMP = ' DB2-FORMAT-TS                             \n626:            EXIT.                                                                \n627:                                                                                 \n628:        9999-ABEND-PROGRAM.                                                      \n629:            DISPLAY 'ABENDING PROGRAM'                                           \n630:            MOVE 0 TO TIMING                                                     \n631:            MOVE 999 TO ABCODE                                                   \n632:            CALL 'CEE3ABD' USING ABCODE, TIMING.                                 \n633:                                                                                 \n634:       *****************************************************************         \n635:        9910-DISPLAY-IO-STATUS.                                                  \n636:            IF  IO-STATUS NOT NUMERIC                                            \n637:            OR  IO-STAT1 = '9'                                                   \n638:                MOVE IO-STAT1 TO IO-STATUS-04(1:1)                               \n639:                MOVE 0        TO TWO-BYTES-BINARY                                \n640:                MOVE IO-STAT2 TO TWO-BYTES-RIGHT                                 \n641:                MOVE TWO-BYTES-BINARY TO IO-STATUS-0403                          \n642:                DISPLAY 'FILE STATUS IS: NNNN' IO-STATUS-04                      \n643:            ELSE                                                                 \n644:                MOVE '0000' TO IO-STATUS-04                                      \n645:                MOVE IO-STATUS TO IO-STATUS-04(3:2)                              \n646:                DISPLAY 'FILE STATUS IS: NNNN' IO-STATUS-04                      \n647:            END-IF                                  