                                  \n487:                CONTINUE                                                         \n488:            ELSE                                                                 \n489:                DISPLAY 'ERROR READING TRANSACTION BALANCE FILE'                 \n490:                MOVE TCATBALF-STATUS TO IO-STATUS                                \n491:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n492:                PERFORM 9999-ABEND-PROGRAM                                       \n493:            END-IF.                                                              \n494:                                                                                 \n495:            IF WS-CREATE-TRANCAT-REC = 'Y'                                       \n496:               PERFORM 2700-A-CREATE-TCATBAL-REC                                 \n497:            ELSE                                                                 \n498:               PERFORM 2700-B-UPDATE-TCATBAL-REC                                 \n499:            END-IF                                                               \n500:                                                                                 \n501:            EXIT.                                                                \n502:       *---------------------------------------------------------------*         \n503:        2700-A-CREATE-TCATBAL-REC.                                               \n504:            INITIALIZE TRAN-CAT-BAL-RECORD                                       \n505:            MOVE XREF-ACCT-ID TO TRANCAT-ACCT-ID                                 \n506:            MOVE DALYTRAN-TYPE-CD TO TRANCAT-TYPE-CD                             \n507:            MOVE DALYTRAN-CAT-CD TO TRANCAT-CD                                   \n508:            ADD DALYTRAN-AMT TO TRAN-CAT-BAL                                     \n509:                                                                                 \n510:            WRITE FD-TRAN-CAT-BAL-RECORD FROM TRAN-CAT-BAL-RECORD                \n511:                                                                                 \n512:            IF  TCATBALF-STATUS = '00'                                           \n513:                MOVE 0 TO APPL-RESULT                                            \n514:            ELSE                                                                 \n515:                MOVE 12 TO APPL-RESULT                                           \n516:            END-IF                                                               \n517:            IF  APPL-AOK                                                         \n518:                CONTINUE                                                         \n519:            ELSE                                                                 \n520:                DISPLAY 'ERROR WRITING TRANSACTION BALANCE FILE'                 \n521:                MOVE TCATBALF-STATUS TO IO-STATUS                                \n522:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n523:                PERFORM 9999-ABEND-PROGRAM                                       \n524:            END-IF.                                                              \n525:       *---------------------------------------------------------------*         \n526:        2700-B-UPDATE-TCATBAL-REC.                                               \n527:            ADD DALYTRAN-AMT TO TRAN-CAT-BAL                                     \n528:            REWRITE FD-TRAN-CAT-BAL-RECORD FROM TRAN-CAT-BAL-RECORD              \n529:                                                                                 \n530:            IF  TCATBALF-STATUS = '00'                                           \n531:                MOVE 0 TO APPL-RESULT                                            \n532:            ELSE                                                                 \n533:                MOVE 12 TO APPL-RESULT                                           \n534:            END-IF                                                               \n535:            IF  APPL-AOK                                                         \n536:                CONTINUE                                                         \n537:            ELSE                                                                 \n538:                DISPLAY 'ERROR REWRITING TRANSACTION BALANCE FILE'               \n539:                MOVE TCATBALF-STATUS TO IO-STATUS                                \n540:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n541:                PERFORM 9999-ABEND-PROGRAM                                       \n542:            END-IF.                                                              \n543:                                                                                 \n544:       *---------------------------------------------------------------*         \n545:        2800-UPDATE-ACCOUNT-REC.                                                 \n546:       * Update the balances in account record to reflect posted trans.          \n547:            ADD DALYTRAN-AMT  TO ACCT-CURR-BAL                                   \n548:            IF DALYTRAN-AMT >= 0                                                 \n549:               ADD DALYTRAN-AMT TO ACCT-CURR-CYC-CREDIT                          \n550:            ELSE                                                                 \n551:               ADD DALYTRAN-AMT TO ACCT-CURR-CYC-DEBIT                           \n552:            END-IF                                                               \n553:                                                                                 \n554:            REWRITE FD-ACCTFILE-REC FROM  ACCOUNT-RECORD                         \n555:               INVALID KEY                                                       \n556:                 MOVE 109 TO WS-VALIDATION-FAIL-REASON                           \n557:                 MOVE 'ACCOUNT RECORD NOT FOUND'                                 \n558:                   TO WS-VALIDATION-FAIL-REASON-DESC                             \n559:            END-REWRITE.                                                         \n560:            EXIT.                                                                \n561:       *---------------------------------------------------------------*         \n562:        2900-WRITE-TRANSACTION-FILE.                                             \n563:            MOVE 8 TO  APPL-RESULT.                                              \n564:            WRITE FD-TRANFILE-REC FROM TRAN-RECORD                               \n565:                                                                                 \n566:            IF  TRANFILE-STATUS = '00'                                           \n567:                MOVE 0 TO  APPL-RESULT                                           \n568:            ELSE                                                                 \n569:                MOVE 12 TO APPL-RESULT                                           \n570:            END-IF                                                               \n571:            IF  APPL-AOK                                                         \n572:                CONTINUE                                                         \n573:            ELSE                                                                 \n574:                DISPLAY 'ERROR WRITING TO TRANSACTION FILE'                      \n575:                MOVE TRANFILE-STATUS  TO IO-STATUS                               \n576:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n577:                PERFORM 9999-ABEND-PROGRAM                                       \n578:            END-IF                                                               \n579:            EXIT.                                                                \n580:                                                                                 \n581:       *---------------------------------------------------------------*         \n582:        9000-DALYTRAN-CLOSE.                                                     \n583:            MOVE 8 TO  APPL-RESULT.                                              \n584:            CLOSE DALYTRAN-FILE                                                  \n585:            IF  DALYTRAN-STATUS = '00'                                           \n586:                MOVE 0 TO APPL-RESULT                                            \n587:            ELSE                                                                 \n588:                MOVE 12 TO APPL-RESULT                                           \n589:            END-IF                                                               \n590:            IF  APPL-AOK                                                         \n591:                CONTINUE                                                         \n592:            ELSE                                                                 \n593:                DISPLAY 'ERROR CLOSING DALYTRAN FILE'                            \n594:                MOVE DALYTRAN-STATUS TO IO-STATUS                                \n595:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n596:                PERFORM 9999-ABEND-PROGRAM                                       \n597:            END-IF                                                               \n598:            EXIT.                                                                \n599:       *---------------------------------------------------------------*         \n600:        9100-TRANFILE-CLOSE.                                                     \n601:            MOVE 8 TO  APPL-RESULT.                                              \n602:            CLOSE TRANSACT-FILE                                                  \n603:            IF  TRANFILE-STATUS = '00'                                           \n604:                MOVE 0 TO  APPL-RESULT                                           \n605:            ELSE                                                                 \n606:                MOVE 12 TO APPL-RESULT                                           \n607:            END-IF                                                               \n608:            IF  APPL-AOK                                                         \n609:                CONTINUE                                                         \n610:            ELSE                                                                 \n611:                DISPLAY 'ERROR CLOSING TRANSACTION FILE'                         \n612:                MOVE TRANFILE-STATUS  TO IO-STATUS                               \n613:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n614:                PERFORM 9999-ABEND-PROGRAM                                       \n615:            END-IF                                                               \n616:            EXIT.                                                                \n617:                                                                                 \n618:       *---------------------------------------------------------------*         \n619:        9200-XREFFILE-CLOSE.                                                     \n620:            MOVE 8 TO APPL-RESULT.                                               \n621:            CLOSE XREF-FILE                                                      \n622:            IF  XREFFILE-STATUS = '00'                                           \n623:                MOVE 0 TO APPL-RESULT                                            \n624:            ELSE                                                                 \n625:                MOVE 12 TO APPL-RESULT                                           \n626:            END-IF                                                               \n627:            IF  APPL-AOK                                                         \n628:                CONTINUE                                                         \n629:            ELSE                                                                 \n630:                DISPLAY 'ERROR CLOSING CROSS REF FILE'                           \n631:                MOVE XREFFILE-STATUS TO IO-STATUS                                \n632:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n633:                PERFORM 9999-ABEND-PROGRAM                                       \n634:            END-IF                                                               \n635:            EXIT.                                                                \n636:       *---------------------------------------------------------------*         \n637:        9300-DALYREJS-CLOSE.                                                     \n638:            MOVE 8 TO APPL-RESULT.                                               \n639:            CLOSE DALYREJS-FILE                                                  \n640:            IF  DALYREJS-STATUS = '00'                                           \n641:                MOVE 0 TO APPL-RESULT                                            \n642:            ELSE                                                                 \n643:                MOVE 12 TO APPL-RESULT                                           \n644:            END-IF                                                               \n645:            IF  APPL-AOK                                                         \n646:                CONTINUE                                                         \n647:            ELSE                                                                 \n648:                DISPLAY 'ERROR CLOSING DAILY REJECTS FILE'                       \n649:                MOVE XREFFILE-STATUS TO IO-STATUS                                \n650:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n651:                PERFORM 9999-ABEND-PROGRAM                                       \n652:            END-IF                                                               \n653:            EXIT.                                                                \n654:       *---------------------------------------------------------------*         \n655:        9400-ACCTFILE-CLOSE.                                                     \n656:            MOVE 8 TO APPL-RESULT.                                               \n657:            CLOSE ACCOUNT-FILE                                                   \n658:            IF  ACCTFILE-STATUS  = '00'                                          \n659:                MOVE 0 TO APPL-RESULT                                            \n660:            ELSE                                                                 \n661:                MOVE 12 TO APPL-RESULT                                           \n662:            END-IF                                                               \n663:            IF  APPL-AOK                                                         \n664:                CONTINUE                                                         \n665:            ELSE                                                                 \n666:                DISPLAY 'ERROR CLOSING ACCOUNT FILE'                             \n667:                MOVE ACCTFILE-STATUS  TO IO-STATUS                               \n668:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n669:                PERFORM 9999-ABEND-PROGRAM                                       \n670:            END-IF                                                               \n671:            EXIT.                                                                \n672:                                                                                 \n673:       *---------------------------------------------------------------*         \n674:        9500-TCATBALF-CLOSE.                                                     \n675:            MOVE 8 TO APPL-RESULT.                                               \n676:            CLOSE TCATBAL-FILE                                                   \n677:            IF  TCATBALF-STATUS  = '00'                                          \n678:                MOVE 0 TO APPL-RESULT                                            \n679:            ELSE                                                                 \n680:                MOVE 12 TO APPL-RESULT                                           \n681:            END-IF                                                               \n682:            IF  APPL-AOK                                                         \n683:                CONTINUE                                                         \n684:            ELSE                                                                 \n685:                DISPLAY 'ERROR CLOSING TRANSACTION BALANCE FILE'                 \n686:                MOVE TCATBALF-STATUS  TO IO-STATUS                               \n687:                PERFORM 9910-DISPLAY-IO-STATUS                                   \n688:                PERFORM 9999-ABEND-PROGRAM                                       \n689:            END-IF                                                               \n690:            EXIT.                                                                \n691:                                                                                 \n692:        Z-GET-DB2-FORMAT-TIMESTAMP.                                              \n693:            MOVE FUNCTION CURRENT-DATE TO COBOL-TS                               \n694:            MOVE COB-YYYY TO DB2-YYYY                                            \n695:            MOVE COB-MM   TO DB2-MM                                              \n696:            MOVE COB-DD   TO DB2-DD                                              \n697:            MOVE COB-HH   TO DB2-HH                                              \n698:            MOVE COB-MIN  TO DB2-MIN                                             \n699:            MOVE COB-SS   TO DB2-SS                                              \n700:            MOVE COB-MIL  TO DB2-MIL                                             \n701:            MOVE '0000'   TO DB2-REST                                            \n702:            MOVE '-' TO DB2-STREEP-1 DB2-STREEP-2 DB2-STREEP-3                   \n703:            MOVE '.' TO DB2-DOT-1 DB2-DOT-2 DB2-DOT-3                            \n704:       *    DISPLAY 'DB2-TIMESTAMP = ' DB2-FORMAT-TS                             \n705:            EXIT.                                                                \n706:                                                                                 \n707:        9999-ABEND-PROGRAM.                                                      \n708:            DISPLAY 'ABENDING PROGRAM'                                           \n709:            MOVE 0 TO TIMING                                                     \n710:            MOVE 999 TO ABCODE                                                   \n711:            CALL 'CEE3ABD' USING ABCODE, TIMING.                                 \n712:                                                                                 \n713:       *****************************************************************         \n714:        9910-DISPLAY-IO-STATUS.                                                  \n715:            IF  IO-STATUS NOT NUMERIC                                            \n716:            OR  IO-STAT1 = '9'                                                   \n717:                MOVE IO-STAT1 TO IO-STATUS-04(1:1)                               \n718:                MOVE 0        TO TWO-BYTES-BINARY                                \n719:                MOVE IO-STAT2 TO TWO-BYTES-RIGHT                                 \n720:                MOVE TWO-BYTES-BINARY TO IO-STATUS-0403                          \n721:                DISPLAY 'FILE STATUS IS: NNNN' IO-STATUS-04                      \n722:            ELSE                                                                 \n723:                MOVE '0000' TO IO-STATUS-04                                      \n724:                MOVE IO-STATUS TO IO-STATUS-04(3:2)                              \n725:                DISPLAY 'FILE STATUS IS: NNNN' IO-STATUS-04                      \n726:            END-IF                                                               \n727:            EXIT.                                                                \n728:                                                                                 \n729:       *\n730:       * Ver: CardDemo_v2.0-25-gdb72e6b-235 Date: 2025-04-29 11:01:29 CDT\n731:       *",
